exercises.title:
What is the output of:
let x = 5;
if (x > 3) {
  console.log("big");
} else {
  console.log("small");
}

What is the output of:
let age = 15;
if (age >= 18) {
  console.log("adult");
} else {
  console.log("minor");
}

What is the output of:
let colour = "red";
if (colour === "green") {
  console.log("go");
} else {
  console.log("stop");
}
